const scene=new T.Scene();scene.background=new T.Color('#273d3c');scene.fog=new T.FogExp2('#273d3c',.006);const camera=new T.PerspectiveCamera(40,innerWidth/innerHeight,.1,400);const renderer=new T.WebGLRenderer({antialias:true});renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.setClearColor('#273d3c');$('world').append(renderer.domElement);scene.add(new T.HemisphereLight(0xe0efdb,0x364b43,2.6));const sun=new T.DirectionalLight(0xffe2b0,3);sun.position.set(-30,60,25);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-50,right:50,top:50,bottom:-50});sun.shadow.bias=-.001;scene.add(sun);
const materials={};function mat(color){return materials[color]??=new T.MeshStandardMaterial({color,roughness:.85})}function box(x,y,z,w,h,d,color,parent=scene){const m=new T.Mesh(new T.BoxGeometry(w,h,d),mat(color));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}function cylinder(x,y,z,r,h,color,n=12,parent=scene){const m=new T.Mesh(new T.CylinderGeometry(r,r,h,n),mat(color));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
