function building(x,z,w,d,h,color,type=0){box(x,h/2,z,w,h,d,color);box(x,h+.17,z,w+.35,.35,d+.35,'#4c6257');if(type===1){const roof=new T.Mesh(new T.ConeGeometry(w*.82,2.5,4),mat('#a27051'));roof.rotation.y=Math.PI/4;roof.position.set(x,h+1.35,z);scene.add(roof)}for(let yy=1.1;yy<h-.2;yy+=1.7){for(let xx=-w/2+.7;xx<w/2-.3;xx+=1.4){box(x+xx,yy,z+d/2+.02,.65,.8,.06,'#dfcea0');box(x+xx,yy,z-d/2-.02,.65,.8,.06,'#627e76')}for(let zz=-d/2+.7;zz<d/2-.3;zz+=1.4)box(x+w/2+.02,yy,z+zz,.06,.8,.65,'#d4c9a4')}box(x,.7,z+d/2+.05,.8,1.4,.1,'#4c6257');}
const palette=['#c3bba1','#b5bea3','#c9af8e','#a6b5a0','#d0c9ac'];let n=0;for(let x of [-25,-13,3,17])for(let z of [-20,-14,15,22]){if(x===17&&z===22)continue;building(x,z,3.5+(n%2),3.4,2.8+(n%4)*1.7,palette[n%5],n%3===0?1:0);n++}
