function tree(x,z,s=1){cylinder(x,.7*s,z,.16*s,1.4*s,'#77684f',6);const m=new T.Mesh(new T.IcosahedronGeometry(1.15*s,1),mat(['#6e8e60','#829d68','#547957'][Math.floor(Math.random()*3)]));m.position.set(x,1.9*s,z);m.castShadow=true;scene.add(m)}for(let i=0;i<75;i++){let x=(Math.random()-.5)*59,z=(Math.random()-.5)*52;if(x>20&&x<28)continue;if(Math.abs(z-8)<2||Math.abs(z+8)<2||[-20,-4,12].some(a=>Math.abs(x-a)<2))continue;if(Math.abs(x-3)<7&&Math.abs(z)<6)continue;tree(x,z,.65+Math.random()*.5)}
