function label(text,x,z){const canvas=document.createElement('canvas');canvas.width=512;canvas.height=80;const c=canvas.getContext('2d');c.fillStyle='rgba(18,40,33,.8)';c.roundRect(0,0,512,80,25);c.fill();c.fillStyle='#e1e6ce';c.font='500 26px sans-serif';c.textAlign='center';c.fillText(text,256,50);const sprite=new T.Sprite(new T.SpriteMaterial({map:new T.CanvasTexture(canvas),depthTest:false,transparent:true,opacity:.85}));sprite.position.set(x,10,z);sprite.scale.set(9,1.4,1);scene.add(sprite)}label('CIVIC QUARTER',3,-16);label('THE MARKET',-13,1);label('RIVERSIDE',19,16);
const meshes=new Map(),colors=['#e6b465','#89c9b5','#b4a2d1'];function syncMeshes(){for(const c of sim.citizens){if(!meshes.has(c.id)){const group=new T.Group();cylinder(0,.7,0,.22,.7,colors[c.faction],8,group);const head=new T.Mesh(new T.SphereGeometry(.21,8,6),mat('#e2c5a0'));head.position.y=1.23;group.add(head);box(-.1,.2,0,.12,.45,.14,'#354c45',group);box(.1,.2,0,.12,.45,.14,'#354c45',group);group.userData.id=c.id;group.traverse(o=>o.userData.id=c.id);scene.add(group);meshes.set(c.id,group)}}for(const [id,m]of meshes)if(!sim.citizens.some(c=>c.id===id)){scene.remove(m);meshes.delete(id)}}syncMeshes();
const ring=new T.Mesh(new T.RingGeometry(.55,.68,32),new T.MeshBasicMaterial({color:0xe5f4bd,side:T.DoubleSide}));ring.rotation.x=-Math.PI/2;scene.add(ring);
let down;renderer.domElement.addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY,button:e.button,moved:false};renderer.domElement.setPointerCapture(e.pointerId)});renderer.domElement.addEventListener('pointermove',e=>{if(!down)return;let dx=e.clientX-down.x,dy=e.clientY-down.y;if(Math.abs(dx)+Math.abs(dy)>2)down.moved=true;if(down.button===2||e.shiftKey){target.x-=dx*.045;target.z-=dy*.045}else{angle-=dx*.006;elevation=Math.max(.25,Math.min(1.3,elevation+dy*.004))}down.x=e.clientX;down.y=e.clientY});renderer.domElement.addEventListener('pointerup',e=>{if(down&&!down.moved){const ray=new T.Raycaster();ray.setFromCamera(new T.Vector2(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1),camera);const hits=ray.intersectObjects([...meshes.values()],true);if(hits.length)select(hits[0].object.userData.id)}down=null});renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();distance=Math.max(20,Math.min(140,distance+e.deltaY*.035))},{passive:false});onresize=()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)};
function select(id){selected=id;$('inspector').classList.remove('hidden');$('drawer').classList.add('hidden');drawer='';update()}
function update(){const citizens=sim.citizens;$('clock').textContent=`DAY ${Math.floor(sim.day)} · ${String(Math.floor((sim.day%1)*24)).padStart(2,'0')}:00`;$('population').textContent=citizens.length;$('happiness').textContent=`${Math.round(citizens.reduce((s,c)=>s+(c.energy+c.hunger+c.social)/3,0)/Math.max(1,citizens.length))}%`;$('treasury').textContent=Math.round(sim.treasury).toLocaleString();$('peace').textContent=sim.tension>65?'Conflict':sim.tension>40?'Tense':'Peace';$('weatherLabel').textContent=sim.weather==='Rain'?'☂ RAIN':'☀ CLEAR';$('tax').textContent=`${Math.round(sim.tax*100)}% TAX`;$('government').textContent=`${citizens.find(c=>c.id===sim.leader)?.name||'Vacant council'} · Food reserve ${Math.floor(sim.food)} · Price ¤${(1+Math.max(0,(100-sim.food)/30)).toFixed(1)}`;$('events').innerHTML=sim.events.slice(0,5).map(e=>`<div class="event"><time>DAY ${e.day}</time>${e.text}</div>`).join('');const c=citizens.find(c=>c.id===selected);if(!c){$('detail').innerHTML='<p>This citizen has passed away. Choose another from Citizens.</p>';return}const mood=c.hunger<30?'Anxious':c.energy<30?'Exhausted':c.social>65?'Connected':'Hopeful';$('detail').innerHTML=`<h2>${c.name}</h2><div class="sub">${c.job} · Age ${Math.floor(c.age)} · ${factions[c.faction]}</div><span class="mood">● ${mood} &nbsp; · &nbsp; ${c.action}</span><div class="section-title">LIVE THOUGHT MAP</div><div class="mind"><div class="node"><small>LONG-TERM PURPOSE</small>${c.goal}</div><div class="stem"></div><div class="branches"><div class="node"><small>STRONGEST NEED</small>${c.hunger<c.energy?'Food & security':'Rest & recovery'}</div><div class="node"><small>CURRENT INTENTION</small>${c.action}</div></div><div class="stem"></div><div class="node"><small>ADAPTIVE DRIVE UPDATE</small>${c.adaptation}</div></div><div class="quote">“${c.action==='Eating'?'A meal first. The rest can wait.':c.action==='Resting'?'I need a quiet moment to regain my strength.':c.action==='Socializing'?'There is more to life than work. I want to know my neighbors.':c.action==='Defending'?'Our neighborhood must be protected.':`My work as a ${c.job.toLowerCase()} gives me a place here. ${c.wealth>100?'Perhaps I can build something lasting.':'I hope tomorrow brings a little more security.'}`}”</div><div class="section-title">NEEDS & EVOLVING DRIVES <span>¤${Math.floor(c.wealth)}</span></div>${['hunger','energy','social','empathy','ambition','caution','aggression'].map(k=>`<div class="barrow"><span>${k==='hunger'?'Nourishment':k[0].toUpperCase()+k.slice(1)}</span><span>${Math.round(c[k])}%</span></div><div class="bar"><i style="width:${c[k]}%"></i></div>`).join('')}<div class="divider"></div><div class="section-title">HOUSEHOLD</div><p class="mem">${c.partner!==null?citizens.find(p=>p.id===c.partner)?.name||'Partner deceased':'No partner'} · ${c.children} children</p><div class="section-title">MEMORY VAULT</div>${c.memories.slice(0,4).map(m=>`<p class="mem">${m}</p>`).join('')}`;}
function showPeople(){drawer='people';$('drawer').classList.remove('hidden');$('drawer').innerHTML='<div class="section-title">CITIZEN DIRECTORY <span>'+sim.citizens.length+' MINDS</span></div><input id="search" placeholder="Find a citizen or profession…" aria-label="Find a citizen"><div id="list"></div>';$('search').oninput=filter;filter()}
function filter(){const q=$('search').value.toLowerCase();$('list').innerHTML='';for(const c of sim.citizens.filter(c=>(c.name+' '+c.job).toLowerCase().includes(q))){const b=document.createElement('button');b.className='person';b.innerHTML=`${c.name}<small>${c.job}</small>`;b.onclick=()=>{select(c.id);target.set(c.x,0,c.z);distance=40};$('list').append(b)}}
document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{speed=+b.dataset.speed;document.querySelectorAll('[data-speed]').forEach(x=>x.classList.toggle('active',x===b))});$('close').onclick=()=>$('inspector').classList.add('hidden');$('orbit').onclick=()=>{auto=!auto;$('orbit').classList.toggle('active',auto)};$('home').onclick=()=>{target.set(0,0,0);distance=81;angle=.78;elevation=.76};$('people').onclick=()=>{if(drawer==='people'){drawer='';$('drawer').classList.add('hidden')}else showPeople()};$('catalyst').onclick=()=>{if(drawer==='env'){drawer='';$('drawer').classList.add('hidden');return}drawer='env';$('drawer').classList.remove('hidden');$('drawer').innerHTML='<div class="section-title">ENVIRONMENTAL CATALYSTS</div><p class="mem">Change the conditions. Observe their choices.</p>';for(const [name,desc]of [['Clear','Sunlight returns to the city'],['Rain','Five days of rain improve harvests'],['Abundance','Add 250 food to the granary'],['Scarcity','Crop failure removes 80% of reserves'],['Discovery','New ideas raise ambition and treasury']]){const b=document.createElement('button');b.className='env';b.innerHTML=name+'<small>'+desc+'</small>';b.onclick=()=>{sim.catalyst(name);update()};$('drawer').append(b)}};$('help').onclick=()=>$('guide').showModal();$('guideClose').onclick=()=>$('guide').close();$('reset').onclick=()=>{if(confirm('Replace your saved civilization with a new world?')){sim=new Simulation();selected=0;syncMeshes();update();$('guide').close();save()}};
function save(){try{localStorage.setItem('freecity-v1',JSON.stringify(sim))}catch{$('toast').textContent='Browser storage unavailable. This session cannot be saved.';$('toast').style.display='block'}}setInterval(save,10000);addEventListener('pagehide',save);let prior=performance.now(),acc=0;function frame(now){requestAnimationFrame(frame);let dt=Math.min((now-prior)/1000,.1);prior=now;acc+=dt*speed;let count=0;while(acc>.12&&count<40){sim.step();acc-=.12;count++}if(count)syncMeshes();for(const c of sim.citizens){let dx=c.tx-c.x,dz=c.tz-c.z,l=Math.hypot(dx,dz),step=Math.min(l,dt*speed*1.3);if(l>.1){c.x+=dx/l*step;c.z+=dz/l*step}const m=meshes.get(c.id);m.position.set(c.x,Math.sin(now*.009+c.id)*.04*(speed?1:0),c.z);m.scale.setScalar(c.age<18?.65:1);if(l>.1)m.rotation.y=Math.atan2(dx,dz)}const c=sim.citizens.find(c=>c.id===selected);ring.visible=!!c;if(c)ring.position.set(c.x,.24,c.z);if(auto)angle+=dt*.06;camera.position.set(target.x+Math.sin(angle)*Math.cos(elevation)*distance,Math.sin(elevation)*distance,target.z+Math.cos(angle)*Math.cos(elevation)*distance);camera.lookAt(target);sun.intensity=sim.weather==='Rain'?1.3:3;if(now-lastUI>650){update();lastUI=now}renderer.render(scene,camera)}update();requestAnimationFrame(frame);
